# Let's find max clique size using simple search
import itertools

def max_clique_bruteforce(adj, n, limit=5):
    # Check cliques up to size limit
    for k in range(limit, 2, -1):
        for combo in itertools.combinations(range(n), k):
            ok = True
            for i in range(k):
                for j in range(i+1, k):
                    if combo[j] not in adj[combo[i]]:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                return k, combo
    return 0, None

