def get_saturation(v, colors):
    used = set()
    for nb in adj[v]:
        if colors[nb] != -1:
            used.add(colors[nb])
    return len(used)

def get_available(v, colors):
    used = set()
    for nb in adj[v]:
        if colors[nb] != -1:
            used.add(colors[nb])
    return [c for c in range(4) if c not in used]

def select_vertex(colors):
    best = -1
    best_sat = -1
    best_deg = -1
    for v in range(n):
        if colors[v] == -1:
            sat = get_saturation(v, colors)
            deg = len(adj[v])
            if sat > best_sat or (sat == best_sat and deg > best_deg):
                best_sat = sat
                best_deg = deg
                best = v
    return best

def backtrack(colors):
    v = select_vertex(colors)
    if v == -1:
        return True
    avail = get_available(v, colors)
    if not avail:
        return False
    # Try colors in some order - maybe least constraining first
    for c in avail:
        colors[v] = c
        if backtrack(colors):
            return True
        colors[v] = -1
    return False

if backtrack(colors):
    print("Found coloring:", colors)
else:
    print("No coloring found")
